def event_types(product_name: str) -> list[SmartContractEventType]:
    """Return the event types for the credit card interest accrual feature."""
    return [
        SmartContractEventType(
            name=ACCRUAL_EVENT, scheduler_tag_ids=[f"{product_name.upper()}_{ACCRUAL_EVENT}_AST"]
        )
    ]


