def get_parameters(
    vault: SmartContractVault, param_fetcher_id: str = INTEREST_ACCRUAL_POF_ID
) -> dict[str, datetime | Decimal | str | None]:
    """Retrieves configuration parameters for the credit card interest accrual feature.

    Args:
        vault: The SmartContractVault instance to query.
        param_fetcher_id: The unique identifier for the parameter fetcher.

    Returns:
        Parameters for the interest accrual feature.
    """
    return vault.get_parameters_observation(fetcher_id=param_fetcher_id).parameters


def _append_to_state(
    state: state_utils.SmartContractState,
    balance_fetcher_id: str = common_fetchers.EFFECTIVE_DATE_BOF_ID,
    param_fetcher_id: str = INTEREST_ACCRUAL_POF_ID,
) -> state_utils.SmartContractState:
    """Updates the contract state with live balances and specific parameter observations."""
    return state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, param_fetcher_id),
        balances=state.vault.get_balances_observation(fetcher_id=balance_fetcher_id).balances,
    )


def get_scheduled_events(
    state: state_utils.SmartContractState,
    fetchers_config: InterestAccrualFetchersConfig = DEFAULT_INTEREST_ACCRUAL_FETCHERS_CONFIG,
) -> dict[str, ScheduledEvent]:
    """Get scheduled event for daily credit card interest accrual.

    Args:
        state: The current state of the smart contract.
        fetchers_config: Configuration for the fetchers.

    Returns:
        The scheduled events for interest accrual.
    """
    state = state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, fetchers_config.param_fetcher_id),
    )

    rejection = state_utils.check_parameters_exist(
        state=state, param_ids={INTEREST_ACCRUAL_TIME_PARAM.id}
    )
    assert rejection is None, rejection

    accrual_time_str: str = state.parameters[INTEREST_ACCRUAL_TIME_PARAM.id]  # type: ignore
    accrual_time: date_and_time.Time = date_and_time.parse_time_str(accrual_time_str)

    return {
        ACCRUAL_EVENT: ScheduledEvent(
            start_datetime=state.effective_datetime.astimezone(state.vault.events_timezone),
            expression=ScheduleExpression(
                hour=accrual_time.hour,
                minute=accrual_time.minute,
                second=accrual_time.second,
            ),
        )
    }


def _calculate_daily_accrual(
    balance: Decimal,
    annual_rate: Decimal,
    effective_datetime: datetime,
    precision: int,
) -> Decimal:
    """Calculates the daily interest accrual amount.

    Formula: balance * (annual_rate / days_in_year)

    Args:
        balance: The outstanding balance.
        annual_rate: The annual interest rate (e.g. 0.249 for 24.9%).
        effective_datetime: The effective datetime (used to determine days in year).
        precision: The number of decimal places for rounding.

    Returns:
        The daily accrual amount.
    """
    if balance <= 0 or annual_rate <= 0:
        return Decimal(0)

    daily_rate = parameter_utils.yearly_to_daily_rate(
        effective_date=effective_datetime,
        yearly_rate=annual_rate,
        days_in_year="actual",
    )
    accrual = balance * daily_rate

    return accrual.quantize(Decimal(10) ** -precision, rounding=ROUND_HALF_UP)


def _get_balance_at_address(
    balances: BalanceDefaultDict,
    address: str,
    denomination: str,
) -> Decimal:
    """Gets the net balance at a specific address."""
    return balances[(address, DEFAULT_ASSET, denomination, Phase.COMMITTED)].net


def schedule_logic(
    state: state_utils.SmartContractState,
    account_type: str = "",
    fetchers_config: InterestAccrualFetchersConfig = DEFAULT_INTEREST_ACCRUAL_FETCHERS_CONFIG,
) -> list[CustomInstruction]:
    """Calculates and accrues daily interest on purchase and cash advance balances.

    Interest is receivable (asset to the lender). Uses create_payable_accrual_custom_instruction
    with payable=False.

    Args:
        state: The current state of the smart contract.
        account_type: The account type for GL impact details.
        fetchers_config: Configuration for the fetchers.

    Returns:
        List of custom instructions for the accrual.
    """
    state = _append_to_state(state=state, param_fetcher_id=fetchers_config.param_fetcher_id)

    rejection = state_utils.check_parameters_exist(
        state=state,
        param_ids={
            fetchers_config.denomination_param_id,
            PURCHASE_INTEREST_RATE_PARAM.id,
            CASH_ADVANCE_INTEREST_RATE_PARAM.id,
            INTEREST_ACCRUAL_PRECISION_PARAM.id,
            INTEREST_RECEIVABLE_ACCOUNT_PARAM.id,
        },
    )
    assert rejection is None, rejection

    denomination: str = str(state.parameters[fetchers_config.denomination_param_id])
    purchase_rate: Decimal = state.parameters[PURCHASE_INTEREST_RATE_PARAM.id]  # type: ignore
    cash_advance_rate: Decimal = state.parameters[CASH_ADVANCE_INTEREST_RATE_PARAM.id]  # type: ignore
    precision: int = int(state.parameters[INTEREST_ACCRUAL_PRECISION_PARAM.id])  # type: ignore
    interest_receivable_account: str = state.parameters[INTEREST_RECEIVABLE_ACCOUNT_PARAM.id]  # type: ignore

    instructions: list[CustomInstruction] = []

    # Accrue interest on purchases
    purchase_balance = _get_balance_at_address(
        state.balances, apex_addresses.PURCHASE, denomination
    )
    purchase_accrual = _calculate_daily_accrual(
        balance=purchase_balance,
        annual_rate=purchase_rate,
        effective_datetime=state.effective_datetime,
        precision=precision,
    )
    if purchase_accrual > 0:
        instructions.extend(
            accrual_utils.create_payable_accrual_custom_instruction(
                customer_account=state.vault.account_id,
                customer_address=apex_addresses.INTEREST_ACCRUED_PURCHASE,
                denomination=denomination,
                amount=purchase_accrual,
                internal_account=interest_receivable_account,
                instruction_details=posting_utils.standard_instruction_details(
                    description=f"Daily interest accrual on purchases: {purchase_accrual}",
                    event_type=ACCRUAL_EVENT,
                    gl_impacted=True,
                    account_type=account_type,
                ),
            )
        )

    # Accrue interest on cash advances
    cash_advance_balance = _get_balance_at_address(
        state.balances, apex_addresses.CASH_ADVANCE, denomination
    )
    cash_advance_accrual = _calculate_daily_accrual(
        balance=cash_advance_balance,
        annual_rate=cash_advance_rate,
        effective_datetime=state.effective_datetime,
        precision=precision,
    )
    if cash_advance_accrual > 0:
        instructions.extend(
            accrual_utils.create_payable_accrual_custom_instruction(
                customer_account=state.vault.account_id,
                customer_address=apex_addresses.INTEREST_ACCRUED_CASH_ADVANCE,
                denomination=denomination,
                amount=cash_advance_accrual,
                internal_account=interest_receivable_account,
                instruction_details=posting_utils.standard_instruction_details(
                    description=f"Daily interest accrual on cash advances: {cash_advance_accrual}",
                    event_type=ACCRUAL_EVENT,
                    gl_impacted=True,
                    account_type=account_type,
                ),
            )
        )

    return instructions
